const updateProduct = `-- name: UpdateProduct :one
UPDATE products
SET barcode = ?, code = ?, name = ?, description = ?,
    is_active = ?, price = ?, discount = ?, color = ?, size = ?, currency_code = ?,
    brand = ?, family = ?, kind = ?, season = ?, product_year = ?
WHERE id = ? RETURNING id, barcode, code, name, description, is_active, price, discount, color, size, currency_code, created_at, brand, family, kind, season, product_year, uid
`

type UpdateProductParams struct {
	Barcode      string `json:"barcode"`
	Code         string `json:"code"`
	Name         string `json:"name"`
	Description  string `json:"description"`
	IsActive     int64  `json:"isActive"`
	Price        int64  `json:"price"`
	Discount     int64  `json:"discount"`
	Color        string `json:"color"`
	Size         string `json:"size"`
	CurrencyCode string `json:"currencyCode"`
	Brand        string `json:"brand"`
	Family       string `json:"family"`
	Kind         string `json:"kind"`
	Season       string `json:"season"`
	ProductYear  int64  `json:"productYear"`
	ID           int64  `json:"id"`
}

func (q *Queries) UpdateProduct(ctx context.Context, arg UpdateProductParams) (Product, error) {
	row := q.db.QueryRowContext(ctx, updateProduct,
		arg.Barcode,
		arg.Code,
		arg.Name,
		arg.Description,
		arg.IsActive,
		arg.Price,
		arg.Discount,
		arg.Color,
		arg.Size,
		arg.CurrencyCode,
		arg.Brand,
		arg.Family,
		arg.Kind,
		arg.Season,
		arg.ProductYear,
		arg.ID,
	)
	var i Product
	err := row.Scan(
		&i.ID,
		&i.Barcode,
		&i.Code,
		&i.Name,
		&i.Description,
		&i.IsActive,
		&i.Price,
		&i.Discount,
		&i.Color,
		&i.Size,
		&i.CurrencyCode,
		&i.CreatedAt,
		&i.Brand,
		&i.Family,
		&i.Kind,
		&i.Season,
		&i.ProductYear,
		&i.Uid,
	)
	return i, err
}
